commit 8b757edb3b7a17252fbf562547e4cfb91decc216
Author: Tzvetan Mikov <tmikov@meta.com>
Date:   Fri Jan 12 20:00:51 2024 -0800

    Remove dangerous overload of isAllASCII()

    Summary:
    isAllASCII() had a slow overload that could accidentally be invoked, for
    example when using an iterator instead of a pointer. That overload
    served no useful purpose, so remove it.

    Note that the problem hasn't happened yet. This diff doesn't affect
    performance, it only prevents it in the future.

    Reviewed By: neildhar

    Differential Revision: D52649630

    fbshipit-source-id: 86d59ef1062f4667de1ccb908169ed57a5c897a9
---
 include/hermes/Support/UTF8.h | 20 ++++++++++----------
 lib/Support/UTF8.cpp          |  8 ++++++++
 lib/VM/StringPrimitive.cpp    |  3 +--
 3 files changed, 19 insertions(+), 12 deletions(-)

diff --git a/include/hermes/Support/UTF8.h b/include/hermes/Support/UTF8.h
index 021c8046c..9432e69dd 100644
--- a/include/hermes/Support/UTF8.h
+++ b/include/hermes/Support/UTF8.h
@@ -52,16 +52,6 @@ bool isASCII(Char c) {
 }

 /// \return true if this is a pure ASCII char sequence.
-template <typename Iter>
-inline bool isAllASCII(Iter begin, Iter end) {
-  while (begin < end) {
-    if (!isASCII(*begin))
-      return false;
-    ++begin;
-  }
-  return true;
-}
-
 /// Overload for char* and uint8_t*.
 bool isAllASCII(const uint8_t *start, const uint8_t *end);

@@ -69,6 +59,16 @@ inline bool isAllASCII(const char *start, const char *end) {
   return isAllASCII((const uint8_t *)start, (const uint8_t *)end);
 }

+/// \return true if this is a pure ASCII char sequence.
+/// Overload for char16_t.
+bool isAllASCII(const char16_t *start, const char16_t *end);
+
+/// \return true if this is a pure ASCII char sequence.
+template <typename T>
+inline bool isAllASCII(const T &str) {
+  return isAllASCII(str.data(), str.data() + str.size());
+}
+
 /// Decode a sequence of UTF8 encoded bytes when it is known that the first byte
 /// is a start of an UTF8 sequence.
 /// \tparam allowSurrogates when false, values in the surrogate range are
diff --git a/lib/Support/UTF8.cpp b/lib/Support/UTF8.cpp
index 44dd9b75f..846d2e89f 100644
--- a/lib/Support/UTF8.cpp
+++ b/lib/Support/UTF8.cpp
@@ -169,4 +169,12 @@ bool isAllASCII(const uint8_t *start, const uint8_t *end) {
   return true;
 }

+bool isAllASCII(const char16_t *start, const char16_t *end) {
+  for (; start != end; ++start) {
+    if (*start > 0x7F)
+      return false;
+  }
+  return true;
+}
+
 } // namespace hermes
diff --git a/lib/VM/StringPrimitive.cpp b/lib/VM/StringPrimitive.cpp
index be150a496..14b12f3c6 100644
--- a/lib/VM/StringPrimitive.cpp
+++ b/lib/VM/StringPrimitive.cpp
@@ -198,8 +198,7 @@ CallResult<HermesValue> StringPrimitive::createEfficient(
 CallResult<HermesValue> StringPrimitive::createDynamic(
     Runtime &runtime,
     UTF16Ref str) {
-  return createDynamicWithKnownEncoding(
-      runtime, str, isAllASCII(str.begin(), str.end()));
+  return createDynamicWithKnownEncoding(runtime, str, isAllASCII(str));
 }

 CallResult<HermesValue> StringPrimitive::createDynamicWithKnownEncoding(
